(()=>{
'use strict';
const VERSION='5.0.0';
const SAVE='mandate-v5';
const OWNER_HASH='927b36f02aa93ca5bfcd87facfb0fcae3a6c47942c41415185cfc9a7e90ea902';
const PARTY={Labour:'#d9273e',Conservative:'#2086d7','Liberal Democrats':'#f5a623',Reform:'#16b8c8',Green:'#178b53',SNP:'#f5ce22',Other:'#7d8790'};
const PARTIES=Object.keys(PARTY);
const CAREERS={pm:['Prime Minister Career','Run government, face Parliament, elections and opposition.'],mp:['MP Career','Represent a constituency, vote, rebel, seek promotion and leadership.'],chancellor:['Chancellor Career','Run the Treasury, budgets, forecasts and economic shocks.'],electioneer:['Electioneer Mode','A campaign-first career with the full 25-week election system.'],voter:['Voter Career','React to policy, switch party support and shape your political story.'],reporter:['News Reporter Career','Cover Westminster, attend briefings and build a daily political archive.']};
const POSTWAR_PMS=['Winston Churchill','Anthony Eden','Harold Macmillan','Alec Douglas-Home','Harold Wilson','Edward Heath','James Callaghan','Margaret Thatcher','John Major','Tony Blair','Gordon Brown','David Cameron','Theresa May','Boris Johnson','Liz Truss','Rishi Sunak','Keir Starmer'];
const PM_START={'Winston Churchill':'1951-10-26','Anthony Eden':'1955-04-06','Harold Macmillan':'1957-01-10','Alec Douglas-Home':'1963-10-19','Harold Wilson':'1964-10-16','Edward Heath':'1970-06-19','James Callaghan':'1976-04-05','Margaret Thatcher':'1979-05-04','John Major':'1990-11-28','Tony Blair':'1997-05-02','Gordon Brown':'2007-06-27','David Cameron':'2010-05-11','Theresa May':'2016-07-13','Boris Johnson':'2019-07-24','Liz Truss':'2022-09-06','Rishi Sunak':'2022-10-25','Keir Starmer':'2024-07-05'};
const REGIONS=['Scotland','North East','North West','Yorkshire','West Midlands','East Midlands','East','London','South East','South West','Wales','Northern Ireland'];
const CONSTITUENCY_POOL=['Aberafan Maesteg','Aberdeen North','Aberdeen South','Ashfield','Aylesbury','Birmingham Hall Green and Moseley','Blackpool South','Bristol Central','Cambridge','Canterbury','Cardiff West','Chester North and Neston','Cities of London and Westminster','Clacton','Croydon West','Edinburgh East and Musselburgh','Exeter','Glasgow South West','Hackney North and Stoke Newington','Henley and Thame','Ipswich','Leicester South','Liverpool Riverside','Manchester Central','Newcastle upon Tyne Central and West','North Somerset','Oxford East','Plymouth Sutton and Devonport','Richmond and Northallerton','Sheffield Central','Southend East and Rochford','Taunton and Wellington','Tooting','Uxbridge and South Ruislip','Weston-super-Mare','Winchester','Yeovil','York Central'];
const NAV=['Home','Diary','Government','Parliament','People','Legislation','Economy','United Kingdom','Public Opinion','Media','Elections','World','History','Updates','Settings'];
const MONARCHS=[['1951-01-01','1952-02-05','George VI'],['1952-02-06','2022-09-07','Elizabeth II'],['2022-09-08','2100-01-01','Charles III']];
let cfg={status:'Operational',announcement:'MANDATE 5 — Career Update',releaseChannel:'Stable',latestUpdate:'MANDATE 5 — Westminster'};
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)); const rnd=(a,b)=>Math.floor(Math.random()*(b-a+1))+a; const pick=a=>a[rnd(0,a.length-1)];
const deep=o=>JSON.parse(JSON.stringify(o)); const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
function addDays(d,n){const x=new Date(d+'T12:00:00');x.setDate(x.getDate()+n);return x.toISOString().slice(0,10)}
function normalize(o){const t=Object.values(o).reduce((a,b)=>a+b,0)||1;const x={};PARTIES.forEach(p=>x[p]=Math.round((o[p]||0)*100/t));let dif=100-Object.values(x).reduce((a,b)=>a+b,0);x[Object.keys(x).sort((a,b)=>x[b]-x[a])[0]]+=dif;return x}
function defaultState(){return{version:VERSION,phase:'setup',dark:false,career:null,role:null,playerName:'',playerParty:'Labour',date:'2026-09-25',week:1,view:'Home',termWeeks:0,opposition:false,retired:false,pmScenario:null,approval:43,trust:42,unity:66,stability:64,capital:58,majority:48,budgetBalance:-18.4,polling:{Labour:34,Conservative:29,'Liberal Democrats':13,Reform:12,Green:7,SNP:4,Other:1},economy:{gdp:1.1,inflation:2.8,unemployment:4.4,rates:4.0,wages:3.8,debt:94},partySupport:'Labour',voterMood:55,reporter:{reputation:45,audience:30,access:40},chancellor:{credibility:58,fiscalHeadroom:14.2},mp:{constituency:'Bristol Central',majority:8421,loyalty:70,influence:45,popularity:56,ambition:58},cabinet:[],bills:[],events:[],news:[],dailyReports:[],history:[],diary:[],diaryCompleted:0,election:null,campaign:null,leadership:null,realMPs:[],realMPsLastSync:null,mapMode:'Party Control',selectedSeat:null,archive:[],settings:{difficulty:'Normal',autoEvents:true,eraFeedback:true,compact:false},careerPath:[],updatesSeen:[]}}
function load(){try{const x=JSON.parse(localStorage.getItem(SAVE)||'null');return x?Object.assign(defaultState(),x):defaultState()}catch{return defaultState()}}
let s=load();
function save(){localStorage.setItem(SAVE,JSON.stringify(s))}
function toast(a,b=''){const r=$('#toastRoot');if(!r)return;const d=document.createElement('div');d.className='toast';d.innerHTML=`<strong>${esc(a)}</strong><span>${esc(b)}</span>`;r.append(d);setTimeout(()=>d.remove(),3500)}
function modal(title,body,foot=''){ $('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>${esc(title)}</h2><button class="close-x" data-close>×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div></div>`;$$('[data-close]').forEach(x=>x.onclick=()=>$('#modalRoot').innerHTML='')}
async function sha256(v){const h=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v));return[...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function loadCfg(){try{const r=await fetch('site-config.json?v='+Date.now(),{cache:'no-store'});if(r.ok)cfg={...cfg,...await r.json()}}catch{}}
function monarch(){return(MONARCHS.find(x=>s.date>=x[0]&&s.date<=x[1])||MONARCHS.at(-1))[2]}
function addNews(title,detail,type='Politics'){s.news.unshift({date:s.date,title,detail,type});s.news=s.news.slice(0,80);s.dailyReports.unshift({date:s.date,time:`${rnd(8,21)}:${String(rnd(0,59)).padStart(2,'0')}`,title,detail,type});s.dailyReports=s.dailyReports.slice(0,500)}
function generateCabinet(){const names=['Rachel Morgan','Daniel Price','Aisha Rahman','Tom Bennett','Sophie Clarke','James Patel','Emily Ward','Oliver Hughes','Priya Shah','Marcus Green'];const jobs=['Chancellor of the Exchequer','Home Secretary','Foreign Secretary','Health Secretary','Education Secretary','Defence Secretary','Justice Secretary','Energy Secretary','Transport Secretary','Business Secretary'];return jobs.map((job,i)=>({name:names[i],job,loyalty:rnd(45,90),competence:rnd(45,90),popularity:rnd(35,75),status:'Serving'}))}
function generateDiary(){const role=s.opposition?'Opposition Leader':s.role;let pool=[];
 if(role==='Prime Minister')pool=[['Monday','Intelligence briefing',1],['Monday','Meeting with Chancellor',1],['Tuesday','Cabinet meeting',1],['Tuesday','Parliamentary statement',0],['Wednesday','PMQs',1],['Wednesday','Backbench meeting',0],['Thursday','Constituency visit',0],['Thursday','Foreign leader call',0],['Friday',`Audience with ${monarch()}`,1],['Friday','Weekly government review',1]];
 else if(role==='Opposition Leader')pool=[['Monday','Shadow Cabinet',1],['Tuesday','Policy development',1],['Wednesday','PMQs preparation',1],['Wednesday','Opposition response',1],['Thursday','Target-seat visit',0],['Friday','Weekly strategy review',1]];
 else if(role==='MP')pool=[['Monday','Constituency casework',1],['Tuesday','Commons vote',1],['Wednesday','Committee session',0],['Thursday','Constituency surgery',1],['Friday','Local stakeholder meeting',0]];
 else if(role==='Chancellor')pool=[['Monday','Treasury forecast meeting',1],['Tuesday','Spending settlement',1],['Wednesday','Economic statement',1],['Thursday','Business roundtable',0],['Friday','Fiscal review',1]];
 else if(role==='News Reporter')pool=[['Monday','Morning editorial conference',1],['Tuesday','Westminster briefing',1],['Wednesday','PMQs coverage',1],['Thursday','Interview politician',0],['Friday','Publish weekly analysis',1]];
 else if(role==='Voter')pool=[['Monday','Read policy briefing',1],['Wednesday','React to government decision',1],['Friday','Review party support',1]];
 else pool=[['Monday','Campaign planning',1],['Tuesday','Target-seat analysis',1],['Wednesday','Media grid',1],['Thursday','Campaign event',1],['Friday','Polling review',1]];
 s.diary=pool.map((x,i)=>({id:`${s.week}-${i}`,day:x[0],title:x[1],required:!!x[2],done:false}));s.diaryCompleted=0
}
function startCareer(career,name,party,scenario){s=defaultState();s.career=career;s.playerName=name||'Player';s.playerParty=party||'Labour';s.partySupport=s.playerParty;s.pmScenario=scenario||null;s.phase='career';s.role=career==='pm'?'Prime Minister':career==='mp'?'MP':career==='chancellor'?'Chancellor':career==='voter'?'Voter':career==='reporter'?'News Reporter':'Electioneer';s.cabinet=generateCabinet();s.careerPath=[{date:s.date,role:s.role}];if(career==='pm'){s.termWeeks=0;s.approval=43;s.stability=61;s.unity=63;s.majority=38;if(scenario&&scenario!=='Create your own'){s.playerName=scenario;s.pmScenario=scenario;s.date=PM_START[scenario]||s.date;if(scenario==='Keir Starmer'){s.stability=52;s.unity=57;s.approval=38;addNews('Contemporary premiership scenario begins','This mode simulates the political pressures of governing; gameplay events are fictional rather than claims about real people.','Scenario')}else addNews(`${scenario} premiership scenario begins`,'Historical-career mode uses real officeholder names with simulated gameplay decisions.','Scenario')}}if(career==='electioneer'){beginElection(25,true);return}generateDiary();addNews('Political career begins',`${s.playerName} begins ${s.role} career mode.`);save();render()}
function renderSetup(){return`<div class="setup"><div class="setup-panel"><section class="setup-brand"><div><img src="mandate-logo.svg"><h1>MANDATE</h1><div class="brand-sub">CAREER · GOVERN · CAMPAIGN · SURVIVE</div><p>A complete UK government and opposition career simulator. Your political life continues through victories, defeats, resignations and comebacks.</p></div><small>MANDATE 5 — Westminster · ${VERSION}</small></section><section class="setup-form"><span class="eyebrow">NEW POLITICAL CAREER</span><h2 style="font-family:var(--serif);font-size:30px;margin:6px 0">How will you enter Westminster?</h2><p class="subtle">Choose a career. You can move between roles as your political life develops.</p><div class="career-grid">${Object.entries(CAREERS).map(([k,v],i)=>`<button class="career ${i===0?'active':''}" data-career="${k}"><strong>${esc(v[0])}</strong><span>${esc(v[1])}</span></button>`).join('')}</div><form id="careerForm"><input type="hidden" id="careerType" value="pm"><div class="grid grid-2"><div class="field"><label>Your name</label><input id="playerName" maxlength="40" value="Mason Sanders"></div><div class="field"><label>Party</label><select id="party">${PARTIES.filter(p=>p!=='Other').map(p=>`<option>${p}</option>`).join('')}</select></div></div><div class="field" id="scenarioField"><label>Prime Minister starting scenario</label><select id="scenario"><option>Create your own</option>${POSTWAR_PMS.map(p=>`<option>${p}</option>`).join('')}</select><span class="tiny">Historical officeholder names are used as scenario starting points; later events are simulated.</span></div><button class="btn primary full" type="submit">Begin Career</button></form></section></div></div>`}
function topbar(){let role=s.opposition?'Leader of the Opposition':s.role;return`<div class="topbar"><div class="top-cell"><small>${esc(role)}</small><strong>${esc(s.playerName)}</strong></div><div class="top-cell"><small>Approval / standing</small><strong>${s.approval}%</strong></div><div class="top-cell"><small>${s.opposition?'Opposition seats':'Government majority'}</small><strong>${s.opposition?Math.max(80,Math.round((s.polling[s.playerParty]||20)*4.8)):s.majority>=0?'+'+s.majority:s.majority}</strong></div><div class="top-cell"><small>Party unity</small><strong>${s.unity}%</strong></div><div class="top-cell"><small>Political capital</small><strong>${s.capital}</strong></div><div class="top-cell"><small>${fmt(s.date)}</small><strong>Week ${s.week}</strong></div></div>`}
function shell(){return`<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="mandate-logo.svg"><div class="brand-name">MANDATE</div><div class="brand-sub">WESTMINSTER</div></div><div class="profile-card"><strong>${esc(s.playerName)}</strong><span>${esc(s.opposition?'Leader of the Opposition':s.role)} · ${esc(s.playerParty)}</span></div><nav class="nav-list">${NAV.map(n=>`<button class="nav-btn ${s.view===n?'active':''}" data-view="${n}">${n}</button>`).join('')}</nav><div class="side-bottom"><span class="status-dot"></span>${esc(cfg.status||'Operational')} · ${VERSION}</div></aside><main class="main">${topbar()}${cfg.announcement?`<div style="padding:8px 18px;background:var(--paper);border-bottom:1px solid var(--line);font-size:11px;color:var(--muted)">${esc(cfg.announcement)}</div>`:''}<div class="view">${view()}</div></main></div>`}
function view(){switch(s.view){case'Diary':return diaryView();case'Government':return governmentView();case'Parliament':return parliamentView();case'People':return peopleView();case'Legislation':return legislationView();case'Economy':return economyView();case'United Kingdom':return ukView();case'Public Opinion':return opinionView();case'Media':return mediaView();case'Elections':return electionsView();case'World':return worldView();case'History':return historyView();case'Updates':return updatesView();case'Settings':return settingsView();default:return homeView()}}
function homeView(){const req=s.diary.filter(x=>x.required&&!x.done).length;return`${s.stability<35?`<div class="pressure"><strong>Pressure on ${s.opposition?'Opposition Leader':'Prime Minister'} intensifies</strong><div style="font-size:11px;margin-top:3px">Party discipline is weakening. Complete the diary and stabilise your position.</div></div>`:''}<div class="hero"><div><span class="eyebrow">${s.opposition?'HM OPPOSITION':'STATE OF THE COUNTRY'}</span><h1>Good ${new Date().getHours()<12?'morning':'afternoon'}, ${esc(s.playerName)}</h1><p>${req?`You have ${req} required diary task${req===1?'':'s'} remaining before this political week can end.`:'Your required diary is complete. You can close the week when ready.'}</p></div><div class="hero-stat"><small>Week completion</small><strong>${Math.round((s.diary.filter(x=>x.done).length/Math.max(1,s.diary.length))*100)}%</strong><button class="btn primary" data-action="endWeek">End Political Week</button></div></div><div class="grid grid-4" style="margin-top:12px">${kpi('Approval',s.approval+'%','Public standing')}${kpi('Stability',s.stability+'%','Government resilience')}${kpi('Party unity',s.unity+'%','Internal discipline')}${kpi('Budget',`£${s.budgetBalance.toFixed(1)}bn`,'Current balance')}</div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-head"><h2>Today & This Week</h2><button class="btn" data-view="Diary">Open Diary</button></div><div class="card-body">${s.diary.slice(0,6).map(t=>taskHtml(t)).join('')}</div></div><div class="card"><div class="card-head"><h2>Developing</h2><span class="badge">Live political feed</span></div><div class="card-body">${s.news.slice(0,5).map(n=>newsHtml(n)).join('')||'<p class="subtle">No major developments yet.</p>'}</div></div></div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-head"><h2>United Kingdom</h2><button class="btn" data-view="United Kingdom">Full map</button></div><div class="card-body">${renderMap(true)}</div></div><div class="card"><div class="card-head"><h2>Career Path</h2></div><div class="card-body"><div class="career-path">${s.careerPath.map(x=>`<span class="career-node">${esc(x.role)} · ${fmt(x.date)}</span>`).join('')}</div><p class="subtle" style="margin-top:12px">Your career can continue through government, opposition, the backbenches and future leadership contests.</p></div></div></div>`}
function kpi(a,b,c){return`<div class="kpi"><small>${esc(a)}</small><strong>${esc(b)}</strong><span>${esc(c)}</span></div>`}
function taskHtml(t){return`<div class="task ${t.done?'done':''} ${t.required?'required':''}"><button data-action="task" data-id="${t.id}">${t.done?'✓':''}</button><div><strong>${esc(t.title)}</strong><div class="tiny">${esc(t.day)}</div></div></div>`}
function newsHtml(n){return`<div class="news-card"><span class="badge">${esc(n.type)}</span><h3>${esc(n.title)}</h3><p>${esc(n.detail)}</p><div class="tiny">${fmt(n.date)}</div></div>`}
function diaryView(){const days=['Monday','Tuesday','Wednesday','Thursday','Friday'];return`<div class="hero"><div><span class="eyebrow">WEEKLY DIARY</span><h1>Week ${s.week}</h1><p>You cannot rush through the simulation. Required engagements must be completed before the week ends.</p></div><div class="hero-stat"><strong>${s.diary.filter(x=>x.done).length}/${s.diary.length}</strong><button class="btn primary" data-action="endWeek">Complete Week</button></div></div><div class="diary-week" style="margin-top:12px">${days.map(d=>`<div class="diary-day"><h3>${d}</h3>${s.diary.filter(x=>x.day===d).map(taskHtml).join('')||'<span class="tiny">No scheduled events</span>'}</div>`).join('')}</div><div class="card" style="margin-top:12px"><div class="card-head"><h2>Daily Political Record</h2><span class="badge">${s.dailyReports.length} entries</span></div><div class="card-body">${s.dailyReports.slice(0,12).map(r=>`<div class="list-row"><span><strong>${esc(r.time)} · ${esc(r.title)}</strong><br><span class="subtle">${esc(r.detail)}</span></span><small>${fmt(r.date)}</small></div>`).join('')||'<p class="subtle">Your archive will build as you complete diary tasks and events.</p>'}</div></div>`}
function completeTask(id){const t=s.diary.find(x=>x.id===id);if(!t||t.done)return;t.done=true;s.diaryCompleted++;let delta=rnd(-1,3);if(t.title.includes('PMQs')){delta=rnd(-3,4);addNews(delta>=0?'Strong PMQs performance':'Difficult PMQs session',delta>=0?'Government benches rally after a confident performance.':'Opposition attacks dominate the afternoon coverage.','Parliament')}else if(t.title.includes('Monarch'))addNews('Weekly audience completed',`The Prime Minister held a constitutional audience with ${monarch()}.`,'Government');else if(t.title.includes('Budget')||t.title.includes('Fiscal'))s.chancellor.credibility=clamp(s.chancellor.credibility+rnd(-2,3),0,100);s.approval=clamp(s.approval+delta,5,90);s.capital=clamp(s.capital+1,0,100);save();render()}
function endWeek(){const left=s.diary.filter(x=>x.required&&!x.done);if(left.length){toast('Diary incomplete',`${left.length} required task${left.length===1?'':'s'} remaining.`);s.view='Diary';render();return}s.week++;s.termWeeks++;s.date=addDays(s.date,7);weeklySimulation();generateDiary();save();render()}
function weeklySimulation(){s.economy.gdp=+(s.economy.gdp+(Math.random()-.48)*.15).toFixed(1);s.economy.inflation=+clamp(s.economy.inflation+(Math.random()-.5)*.18,0.2,12).toFixed(1);s.approval=clamp(s.approval+rnd(-2,2),5,90);s.stability=clamp(s.stability+rnd(-2,2),0,100);s.unity=clamp(s.unity+rnd(-2,2),0,100);if(Math.random()<.42)randomPoliticalEvent();if(s.opposition&&Math.random()<.12)addNews('Opposition gains a campaigning opportunity','A government setback gives the opposition a stronger media week.','Opposition');if(s.role==='Prime Minister'&&!s.opposition&&s.termWeeks>180&&Math.random()<.12)addNews('Election speculation grows','Westminster attention turns increasingly towards the next general election.','Election');if(s.stability<22&&Math.random()<.25)leadershipPressure()}
function randomPoliticalEvent(){const ev=pick(['MP resigns','MP defects','Minister resigns','Cabinet scandal','Backbench rebellion','Government leak','By-election','Strike','Economic shock','Foreign crisis','Polling shock','Court ruling','Constituency controversy']);switch(ev){case'MP resigns':addNews('MP announces resignation',`A ${pick(PARTIES.slice(0,5))} MP will leave Parliament, triggering a vacancy.`);break;case'MP defects':{const a=pick(PARTIES.slice(0,5)),b=pick(PARTIES.slice(0,5).filter(x=>x!==a));addNews('MP crosses the floor',`An MP leaves ${a} and joins ${b}.`,'Parliament');s.unity=clamp(s.unity-rnd(1,4),0,100);break}case'Minister resigns':addNews('Minister resigns from government','A minister leaves office after a difficult political week.','Government');s.stability-=3;break;case'Cabinet scandal':addNews('Cabinet minister faces investigation','Questions over conduct dominate political coverage.','Media');s.trust-=3;break;case'Backbench rebellion':addNews('Backbench rebellion grows','MPs threaten to oppose the party leadership on a major vote.','Parliament');s.unity-=4;break;case'Government leak':addNews('Confidential briefing leaked','A leaked internal document drives the news cycle.','Media');s.trust-=2;break;case'By-election':addNews('Unexpected by-election announced','Parties begin selecting candidates for a new contest.','Election');break;case'Strike':addNews('National strike announced','Ministers and unions prepare for urgent negotiations.','Country');s.approval-=2;break;case'Economic shock':addNews('Economic outlook weakens','Fresh data creates pressure on the Treasury.','Economy');s.economy.gdp-=.3;s.budgetBalance-=2;break;case'Foreign crisis':addNews('International crisis develops','The government convenes an emergency foreign-policy meeting.','World');s.stability-=2;break;case'Polling shock':addNews('New poll jolts Westminster','A surprise poll reshapes party strategy.','Polling');s.approval+=rnd(-4,4);break;case'Court ruling':addNews('Court ruling challenges government policy','Ministers are reviewing the legal implications.','Constitution');break;default:addNews('Local controversy becomes national story','A constituency issue attracts Westminster attention.','Politics')}s.approval=clamp(s.approval,5,90);s.trust=clamp(s.trust,0,100);s.stability=clamp(s.stability,0,100);s.unity=clamp(s.unity,0,100)}
function leadershipPressure(){s.leadership={active:true,support:clamp(s.unity+rnd(-10,10),10,90)};addNews('Leadership challenge pressure intensifies','Senior party figures call for clarity over the leadership.','Party');}
function governmentView(){return`<div class="hero"><div><span class="eyebrow">${s.opposition?'SHADOW GOVERNMENT':'GOVERNMENT HQ'}</span><h1>${s.opposition?'Opposition Command':'Government Command'}</h1><p>Manage people, pressure, priorities and the political survival of your leadership.</p></div><div class="hero-stat"><strong>${s.stability}%</strong><small>stability</small></div></div><div class="grid grid-3" style="margin-top:12px">${kpi('Public trust',s.trust+'%','Confidence in leadership')}${kpi('Political capital',s.capital,'Spend on difficult decisions')}${kpi('Party unity',s.unity+'%','Backbench discipline')}</div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-head"><h2>${s.opposition?'Shadow Cabinet':'Cabinet'}</h2><button class="btn" data-action="reshuffle">Reshuffle</button></div><div class="card-body">${s.cabinet.slice(0,8).map(m=>`<div class="list-row"><span><strong>${esc(m.name)}</strong><br><span class="subtle">${esc(m.job)}</span></span><span>${m.loyalty}% loyalty</span></div>`).join('')}</div></div><div class="card"><div class="card-head"><h2>Leadership</h2></div><div class="card-body"><p class="subtle">A resignation does not have to end the save. You can remain an MP, contest a leadership vote, or follow the elected successor.</p><div class="toolbar"><button class="btn" data-action="resignLeadership">Resign leadership</button><button class="btn" data-action="confidence">Confidence vote</button>${s.opposition?'':`<button class="btn primary" data-action="callElection">Call general election</button>`}</div></div></div></div>`}
function reshuffle(){s.cabinet.forEach(m=>{m.loyalty=clamp(m.loyalty+rnd(-8,8),20,95);m.job=Math.random()<.2?pick(s.cabinet.map(x=>x.job)):m.job});s.capital=clamp(s.capital-5,0,100);addNews('Major reshuffle completed','Several ministers move roles as the leadership resets the government.','Government');save();render()}
function resignLeadership(){modal('Resign as leader',`<p>Your political career can continue after resignation.</p><div class="grid grid-2"><button class="btn" id="stayMP">Remain as an MP</button><button class="btn primary" id="contest">Trigger leadership election</button></div>`,`<button class="btn" data-close>Cancel</button>`);$('#stayMP').onclick=()=>{s.role='MP';s.opposition=false;s.careerPath.push({date:s.date,role:'Backbench MP'});generateDiary();$('#modalRoot').innerHTML='';addNews(`${s.playerName} resigns as party leader`,'The former leader returns to the backbenches.','Party');save();render()};$('#contest').onclick=()=>leadershipElection()}
function leadershipElection(){const win=Math.random()<.5;modal('Party Leadership Election',`<h3>${win?'You win the leadership vote':'Another MP wins the leadership vote'}</h3><p>${win?'Party members and MPs return you to the leadership.':'You may remain a backbench MP, or switch character to the winning leader and continue the premiership story.'}</p>${win?'':`<div class="toolbar"><button class="btn" id="remainMP">Remain as MP</button><button class="btn primary" id="followWinner">Follow the winner</button></div>`}`,`<button class="btn" data-close>Close</button>`);if(win){s.role=s.opposition?'Opposition Leader':'Prime Minister';s.careerPath.push({date:s.date,role:s.role});addNews(`${s.playerName} wins leadership election`,'The party confirms its leader after a closely fought contest.','Party');save()}else{setTimeout(()=>{if($('#remainMP'))$('#remainMP').onclick=()=>{s.role='MP';s.opposition=false;s.careerPath.push({date:s.date,role:'Backbench MP'});generateDiary();$('#modalRoot').innerHTML='';save();render()};if($('#followWinner'))$('#followWinner').onclick=()=>{s.playerName=pick(['Alex Morgan','Sarah Bennett','Daniel Clarke','Priya Shah']);s.role=s.opposition?'Opposition Leader':'Prime Minister';s.careerPath.push({date:s.date,role:s.role});generateDiary();$('#modalRoot').innerHTML='';addNews('Leadership changes hands','The game continues from the perspective of the newly elected leader.','Party');save();render()}},0)}}
function confidence(){const won=Math.random()<(s.unity+s.stability)/200;addNews(won?'Leadership survives confidence vote':'Leadership loses confidence vote',won?'The party closes ranks around the leadership.':'The defeat forces a leadership contest.','Party');if(!won)leadershipElection();else{s.unity+=4;s.stability+=4;save();render()}}
function parliamentView(){const seats=seatProjection();return`<div class="grid grid-2"><div class="card"><div class="card-head"><h2>House of Commons</h2><span class="badge">650 seats</span></div><div class="card-body">${PARTIES.map(p=>`<div class="list-row"><span><i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${PARTY[p]};margin-right:7px"></i>${esc(p)}</span><strong>${seats[p]||0}</strong></div>`).join('')}</div></div><div class="card"><div class="card-head"><h2>Parliamentary Actions</h2></div><div class="card-body"><div class="toolbar"><button class="btn" data-action="pmqs">PMQs</button><button class="btn" data-action="rebellion">Simulate rebellion</button><button class="btn" data-action="lords">House of Lords</button><button class="btn" data-action="committee">Select committee</button></div><p class="subtle">MPs can rebel, abstain, defect, resign and trigger by-elections. Lords can amend legislation before Royal Assent.</p></div></div></div>`}
function seatProjection(){let out={};let left=650;PARTIES.forEach((p,i)=>{if(i===PARTIES.length-1)out[p]=left;else{out[p]=Math.max(0,Math.round((s.polling[p]||0)*6.5));left-=out[p]}});if(left<0){let f=650/Object.values(out).reduce((a,b)=>a+b,0);PARTIES.forEach(p=>out[p]=Math.round(out[p]*f))}return out}
async function syncMPs(){toast('Syncing Commons roster','Using the official UK Parliament Members API.');let all=[];try{for(let skip=0;skip<660;skip+=20){const r=await fetch(`https://members-api.parliament.uk/api/Members/Search?House=1&IsCurrentMember=true&skip=${skip}&take=20`);if(!r.ok)throw Error();const j=await r.json();const items=j.items||[];for(const it of items){const v=it.value||it;all.push({id:v.id,name:v.nameDisplayAs||v.nameFullTitle||v.nameAddressAs||'Member of Parliament',party:v.latestParty?.name||v.latestParty?.abbreviation||'Other',constituency:v.latestHouseMembership?.membershipFrom||v.latestHouseMembership?.membershipFromName||v.latestHouseMembership?.membershipFrom||'Constituency'})}if(items.length<20)break}if(!all.length)throw Error();s.realMPs=all;s.realMPsLastSync=new Date().toISOString();save();toast('Commons roster updated',`${all.length} members loaded.`);render()}catch{toast('Roster sync unavailable','The game will use its local simulated MP roster instead.')}}
function peopleView(){const list=s.realMPs.length?s.realMPs:CONSTITUENCY_POOL.map((c,i)=>({name:['Alex Morgan','Emily Ward','Daniel Price','Priya Shah','James Patel','Sophie Clarke'][i%6]+' '+(i+1),party:PARTIES[i%6],constituency:c}));return`<div class="hero"><div><span class="eyebrow">PEOPLE OF PARLIAMENT</span><h1>MPs & Political Careers</h1><p>Use current Commons data when available, with separate fictional simulation traits layered on top.</p></div><div><button class="btn primary" data-action="syncMPs">Sync current Commons roster</button><div class="tiny" style="color:#dbe4e9;margin-top:8px">${s.realMPsLastSync?'Last synced '+new Date(s.realMPsLastSync).toLocaleString():'Not synced yet'}</div></div></div><div class="card" style="margin-top:12px"><div class="card-head"><h2>Members</h2><span class="badge">${list.length} loaded</span></div><div class="card-body">${list.slice(0,80).map((m,i)=>`<div class="list-row"><span><strong>${esc(m.name)}</strong><br><span class="subtle">${esc(m.constituency)}</span></span><span>${esc(m.party)} · influence ${35+(i*7)%60}%</span></div>`).join('')}</div></div>`}
function legislationView(){return`<div class="toolbar" style="margin-bottom:12px"><button class="btn primary" data-action="newBill">Draft Bill</button><button class="btn" data-action="progressBills">Progress parliamentary week</button></div><div class="card"><div class="card-head"><h2>Legislation Tracker</h2></div><div class="card-body">${s.bills.map((b,i)=>`<div class="list-row"><span><strong>${esc(b.name)}</strong><br><span class="subtle">${esc(b.stage)} · ${esc(b.area)}</span></span><span>${b.support}% support · ${esc(b.status)}</span></div>`).join('')||'<p class="subtle">No bills introduced yet.</p>'}</div></div>`}
function newBill(){modal('Draft New Bill',`<div class="field"><label>Bill name</label><input id="billName" value="Public Services Reform Bill"></div><div class="grid grid-2"><div class="field"><label>Area</label><select id="billArea"><option>Economy</option><option>Health</option><option>Education</option><option>Justice</option><option>Housing</option><option>Energy</option></select></div><div class="field"><label>Public support</label><input id="billSupport" type="number" value="55" min="10" max="90"></div></div>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" id="createBill">Introduce Bill</button>`);$('#createBill').onclick=()=>{s.bills.unshift({name:$('#billName').value||'Government Bill',area:$('#billArea').value,support:+$('#billSupport').value,stage:'First Reading',step:0,status:'Active'});$('#modalRoot').innerHTML='';addNews('New bill introduced',s.bills[0].name,'Parliament');save();render()}}
function progressBills(){const stages=['First Reading','Second Reading','Committee','Report','Third Reading','House of Lords','Royal Assent'];s.bills.filter(b=>b.status==='Active').forEach(b=>{if(b.step>0&&Math.random()>(b.support+s.unity)/200){b.status='Defeated';addNews(`${b.name} defeated`,`${b.stage} ends in defeat for the bill.`,'Parliament');return}b.step++;if(b.step>=stages.length-1){b.step=stages.length-1;b.stage='Royal Assent';b.status='Passed';addNews(`${b.name} receives Royal Assent`,'The bill becomes law.','Parliament');s.history.push({date:s.date,title:b.name,type:'Law'})}else b.stage=stages[b.step]});save();render()}
function economyView(){return`<div class="grid grid-4">${kpi('GDP growth',s.economy.gdp+'%','Quarterly trend')}${kpi('Inflation',s.economy.inflation+'%','CPI')}${kpi('Unemployment',s.economy.unemployment+'%','Labour market')}${kpi('Interest rate',s.economy.rates+'%','Policy rate')}</div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-head"><h2>Treasury</h2></div><div class="card-body"><p class="subtle">Chancellor mode adds weekly fiscal diary decisions, credibility and headroom.</p><div class="list-row"><span>Fiscal headroom</span><strong>£${s.chancellor.fiscalHeadroom.toFixed(1)}bn</strong></div><div class="list-row"><span>Credibility</span><strong>${s.chancellor.credibility}%</strong></div><button class="btn primary" data-action="budget">Deliver Budget</button></div></div><div class="card"><div class="card-head"><h2>Economic Risks</h2></div><div class="card-body"><div class="list-row"><span>Cost of living</span><strong>${s.economy.inflation>4?'High':'Moderate'}</strong></div><div class="list-row"><span>Debt</span><strong>${s.economy.debt}% GDP</strong></div><div class="list-row"><span>Business confidence</span><strong>${clamp(62+Math.round(s.economy.gdp*4)-Math.round(s.economy.inflation),10,90)}%</strong></div></div></div></div>`}
function budget(){let good=Math.random()<.58;s.budgetBalance+=good?rnd(1,5):-rnd(1,5);s.approval+=good?2:-2;s.chancellor.credibility+=good?3:-4;addNews(good?'Budget receives positive response':'Budget faces difficult reaction',good?'Markets and voters react steadily to the fiscal package.':'Opposition and commentators question the fiscal package.','Economy');save();render()}
function renderMap(compact=false){const dots=[];for(let i=0;i<650;i++){const region=i%REGIONS.length;const col=PARTY[PARTIES[(i+Math.floor((s.polling[PARTIES[i%PARTIES.length]]||10)/8))%PARTIES.length]];const x=80+((i*37)%205)+Math.sin(i)*12;const y=35+((i*53)%430);dots.push(`<circle class="const-dot" data-seat="${i}" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${compact?1.8:2.3}" fill="${col}"/>`)}return`<div class="map-wrap"><svg class="uk-map" viewBox="0 0 360 520" aria-label="Interactive UK political map"><path d="M183 15l24 22-8 30 21 18-17 29 26 26-10 35 18 22-7 32 20 23-3 42 22 34-5 30 25 24-18 31-11 39-28 12-25-16-22 28-24-9-17 24-34-9-10-30-27-6 8-31-18-24 17-30-11-30 22-19-3-39 20-17-7-33 22-18-1-34 20-22-2-30 19-31-7-34 25-24-4-31 22-28 4-30 25-20z" fill="rgba(255,255,255,.72)" stroke="rgba(25,55,70,.35)" stroke-width="2"/><path d="M82 387l25 11 3 32-21 24-28-6-13-24 13-28z" fill="rgba(255,255,255,.72)" stroke="rgba(25,55,70,.35)" stroke-width="2"/>${dots.join('')}</svg><div class="map-tabs">${['Party Control','Polling','Swing','Approval','Economy','Battlegrounds','Campaign','Events','By-Elections','Election Night'].map(m=>`<button class="${s.mapMode===m?'active':''}" data-map="${m}">${m}</button>`).join('')}</div>${s.selectedSeat!=null?seatPanel(s.selectedSeat):''}<div class="map-legend">${PARTIES.slice(0,6).map(p=>`<div><i style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${PARTY[p]};margin-right:5px"></i>${p}</div>`).join('')}</div></div>`}
function seatPanel(i){const c=CONSTITUENCY_POOL[i%CONSTITUENCY_POOL.length];const party=PARTIES[i%6];return`<div class="const-panel"><h3>${esc(c)}</h3><div class="tiny">Constituency #${i+1}</div><div class="list-row"><span>Current control</span><strong>${party}</strong></div><div class="list-row"><span>Majority</span><strong>${1000+(i*791)%22000}</strong></div><div class="list-row"><span>Local approval</span><strong>${30+(i*13)%45}%</strong></div><div class="list-row"><span>Risk</span><strong>${i%7===0?'Marginal':'Normal'}</strong></div></div>`}
function ukView(){return`<div class="hero"><div><span class="eyebrow">UNITED KINGDOM</span><h1>Political Map</h1><p>Explore constituency control, polling, swing, approval, the economy, campaign activity, events and live election declarations.</p></div></div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-body">${renderMap(false)}</div></div><div class="card"><div class="card-head"><h2>Map Intelligence</h2></div><div class="card-body"><p class="subtle">Select any constituency dot for its simulated local profile. Current MP names can be synchronised from UK Parliament on the People page.</p>${REGIONS.map((r,i)=>`<div class="list-row"><span>${r}</span><strong>${clamp(s.approval+rnd(-8,8),5,90)}% approval</strong></div>`).join('')}</div></div></div>`}
function opinionView(){return`<div class="grid grid-4">${kpi('Approval',s.approval+'%','National')}${kpi('Trust',s.trust+'%','Government')}${kpi('Party unity',s.unity+'%','Internal')}${kpi('Voter mood',s.voterMood+'%','Career-mode mood')}</div>${s.role==='Voter'?`<div class="card" style="margin-top:12px"><div class="card-head"><h2>Voter Career</h2></div><div class="card-body"><p class="subtle">Current support: <strong>${esc(s.partySupport)}</strong>. Policy reactions and political events can move your support.</p><button class="btn primary" data-action="voterAction">React & reconsider party</button></div></div>`:''}<div class="card" style="margin-top:12px"><div class="card-head"><h2>Voting Intention</h2></div><div class="card-body">${PARTIES.map(p=>`<div class="list-row"><span>${p}</span><strong>${s.polling[p]||0}%</strong></div>`).join('')}</div></div>`}
function mediaView(){const oldEra=+s.date.slice(0,4)<1995&&s.settings.eraFeedback;return`<div class="hero"><div><span class="eyebrow">MEDIA & PUBLIC FEEDBACK</span><h1>${oldEra?'Press, Letters & Broadcast':'The Political News Cycle'}</h1><p>${oldEra?'Historical careers replace modern social feedback with newspapers, letters, radio and early television.':'Press conferences, interviews, investigations, leaks and breaking news can all move opinion.'}</p></div></div><div class="toolbar" style="margin:12px 0"><button class="btn" data-action="mediaEvent">${oldEra?'Read morning papers':'Hold press conference'}</button><button class="btn" data-action="reportStory">${s.role==='News Reporter'?'Publish story':'Give interview'}</button></div><div class="card"><div class="card-head"><h2>Newsroom</h2></div><div class="card-body">${s.news.slice(0,18).map(newsHtml).join('')||'<p class="subtle">No stories yet.</p>'}</div></div>`}
function mediaEvent(){const good=Math.random()<.55;s.approval+=good?2:-2;s.trust+=good?1:-2;addNews(good?'Media round goes well':'Difficult media round',good?'The leadership message leads the main bulletins.':'Tough questioning dominates political coverage.','Media');save();render()}
function reportStory(){if(s.role==='News Reporter'){s.reporter.reputation=clamp(s.reporter.reputation+rnd(-2,4),0,100);s.reporter.audience=clamp(s.reporter.audience+rnd(0,3),0,100);addNews('Exclusive report published','Your newsroom publishes a Westminster story and audience grows.','Reporter')}else mediaEvent();save();render()}
function electionsView(){return`<div class="hero"><div><span class="eyebrow">ELECTIONS</span><h1>${s.campaign?`${s.campaign.weeks} weeks to polling day`:'Election Centre'}</h1><p>PM career uses a focused four-week regulated campaign. Electioneer mode preserves the extended 25-week strategy campaign.</p></div><div><button class="btn primary" data-action="callElection">${s.campaign?'Continue campaign':'Start General Election'}</button></div></div><div class="grid grid-3" style="margin-top:12px">${kpi('Last result',s.archive.at(-1)?.result||'—','Career archive')}${kpi('Campaign format',s.career==='electioneer'?'25 weeks':'4 weeks','Career rules')}${kpi('Elections fought',s.archive.length,'This save')}</div>`}
function beginElection(weeks,isElectioneer=false){s.phase='campaign';s.campaign={weeks,weeksTotal:weeks,energy:85,funds:isElectioneer?20:8,momentum:50,actions:[],visits:[],debate:50};s.election=null;save();render()}
function callElection(){if(s.phase==='campaign'){render();return}beginElection(s.career==='electioneer'?25:4,s.career==='electioneer')}
function campaignView(){const c=s.campaign;return`<div class="election-stage"><div style="max-width:1400px;margin:auto"><div class="hero"><div><span class="eyebrow">GENERAL ELECTION</span><h1>${c.weeks===0?'ELECTION DAY':`${c.weeks} WEEKS TO GO`}</h1><p>${esc(s.playerName)} · ${esc(s.playerParty)} · Every campaign week requires at least one major action.</p><div class="campaign-progress"><i style="width:${((c.weeksTotal-c.weeks)/c.weeksTotal)*100}%"></i></div></div><div class="hero-stat"><strong>${s.polling[s.playerParty]}%</strong><small>polling</small></div></div><div class="grid grid-4" style="margin-top:12px">${kpi('Energy',c.energy+'%','Leader stamina')}${kpi('Funds','£'+c.funds.toFixed(1)+'m','Campaign resources')}${kpi('Momentum',c.momentum+'%','Campaign trend')}${kpi('Debate',c.debate+'%','Preparation')}</div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-head"><h2>Campaign Actions</h2></div><div class="card-body"><div class="toolbar"><button class="btn" data-action="campaignAction" data-kind="visit">Visit target seat</button><button class="btn" data-action="campaignAction" data-kind="policy">Policy announcement</button><button class="btn" data-action="campaignAction" data-kind="media">Media appearance</button><button class="btn" data-action="campaignAction" data-kind="debate">Debate prep</button><button class="btn" data-action="campaignAction" data-kind="advert">Advertising</button></div><p class="subtle">Other parties campaign automatically. Polls move after each completed week.</p><button class="btn primary" data-action="campaignWeek">Finish campaign week</button></div></div><div class="card"><div class="card-body">${renderMap(true)}</div></div></div></div></div>`}
function campaignAction(d){const c=s.campaign;if(c.energy<8){toast('Leader exhausted');return}c.energy-=rnd(5,11);let gain=rnd(0,2);if(d.kind==='advert'){if(c.funds<1){toast('Not enough campaign funds');return}c.funds-=1.2}if(d.kind==='debate')c.debate=clamp(c.debate+8,0,100);if(d.kind==='visit')c.visits.push(pick(CONSTITUENCY_POOL));c.momentum=clamp(c.momentum+rnd(-1,4),0,100);c.actions.push({week:c.weeks,kind:d.kind});s.polling[s.playerParty]+=gain;s.polling=normalize(s.polling);save();render()}
function campaignWeek(){const c=s.campaign;if(!c.actions.some(a=>a.week===c.weeks)){toast('Choose a campaign action first');return}Object.keys(s.polling).forEach(p=>{if(p!==s.playerParty)s.polling[p]=Math.max(1,s.polling[p]+rnd(-1,1))});s.polling=normalize(s.polling);c.energy=clamp(c.energy+18,0,100);c.weeks--;if(c.weeks<=0){c.weeks=0;setTimeout(()=>startElectionNight(),0)}save();render()}
function startElectionNight(){const projected=seatProjection();const entries=[];for(let i=0;i<650;i++){const p=weightedParty(s.polling);entries.push({name:CONSTITUENCY_POOL[i%CONSTITUENCY_POOL.length]+' '+(Math.floor(i/CONSTITUENCY_POOL.length)+1),winner:p,declared:false})}s.phase='election';s.election={exit:projected,declared:0,seats:Object.fromEntries(PARTIES.map(p=>[p,0])),entries,complete:false};save();render()}
function weightedParty(polls){let r=Math.random()*100;for(const p of PARTIES){r-=polls[p]||0;if(r<=0)return p}return'Other'}
function electionView(){const e=s.election;return`<div class="election-stage"><div style="max-width:1500px;margin:auto"><div class="hero"><div><span class="eyebrow">22:00 · POLLS CLOSED</span><h1>EXIT POLL</h1><p>Live declarations will update the map and seat totals.</p></div><div class="hero-stat"><strong>${e.declared}/650</strong><small>declared</small></div></div><div class="exit-grid" style="margin-top:12px">${PARTIES.map(p=>`<div class="exit-party" style="background:${PARTY[p]}"><span>${p}</span><strong>${e.exit[p]||0}</strong><small>${e.seats[p]||0} live</small></div>`).join('')}</div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-head"><h2>Election Night</h2></div><div class="card-body"><div class="toolbar"><button class="btn" data-action="declare" data-count="1">Next declaration</button><button class="btn" data-action="declare" data-count="10">10×</button><button class="btn" data-action="declare" data-count="50">50×</button><button class="btn primary" data-action="finishElection">Finish election</button></div>${e.entries.filter(x=>x.declared).slice(-8).reverse().map(x=>`<div class="list-row"><span>${esc(x.name)}</span><strong style="color:${PARTY[x.winner]}">${esc(x.winner)} WIN</strong></div>`).join('')}</div></div><div class="card"><div class="card-body">${renderMap(true)}</div></div></div></div></div>`}
function declare(d){let n=+d.count||1;while(n--&&s.election.declared<650){const x=s.election.entries[s.election.declared];x.declared=true;s.election.seats[x.winner]++;s.election.declared++}if(s.election.declared>=650)completeElection();save();render()}
function finishElection(){while(s.election.declared<650){const x=s.election.entries[s.election.declared];x.declared=true;s.election.seats[x.winner]++;s.election.declared++}completeElection();save();render()}
function completeElection(){if(s.election.complete)return;s.election.complete=true;const seats=s.election.seats;const winner=Object.keys(seats).sort((a,b)=>seats[b]-seats[a])[0];const playerSeats=seats[s.playerParty]||0;const won=winner===s.playerParty;if(won){s.opposition=false;s.role='Prime Minister';s.majority=playerSeats-326;s.stability=62;s.careerPath.push({date:s.date,role:'Prime Minister'});s.archive.push({date:s.date,result:`${s.playerParty} ${playerSeats} seats — government`});addNews(`${s.playerParty} forms the government`,`${s.playerName} enters Downing Street after winning the general election.`,'Election')}else{s.opposition=true;s.role='Opposition Leader';s.majority=seats[winner]-326;s.careerPath.push({date:s.date,role:'Leader of the Opposition'});s.archive.push({date:s.date,result:`${s.playerParty} ${playerSeats} seats — opposition`});addNews(`${winner} wins the election`,`${s.playerName} continues as Leader of the Opposition. The political career does not end.`,'Election')}s.phase='career';s.campaign=null;s.date=addDays(s.date,2);generateDiary();setTimeout(()=>{save();render()},10)}
function worldView(){return`<div class="card"><div class="card-head"><h2>World & Diplomacy</h2></div><div class="card-body"><div class="toolbar"><button class="btn" data-action="worldEvent">International summit</button><button class="btn" data-action="worldEvent">Trade talks</button><button class="btn" data-action="worldEvent">Security briefing</button></div><p class="subtle">International events can affect stability, the economy and the weekly diary.</p></div></div>`}
function worldEvent(){addNews(pick(['International summit concludes','Trade talks enter new phase','Security briefing delivered']),'The government reviews the implications for the United Kingdom.','World');s.capital=clamp(s.capital+rnd(-2,2),0,100);save();render()}
function historyView(){return`<div class="hero"><div><span class="eyebrow">POLITICAL LIFE</span><h1>Career & Premiership Archive</h1><p>Every government, election, law and career transition can survive inside one save.</p></div><button class="btn" data-action="sharePremiership">Share premiership</button></div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-head"><h2>Career Timeline</h2></div><div class="card-body">${s.careerPath.map(x=>`<div class="list-row"><span>${esc(x.role)}</span><strong>${fmt(x.date)}</strong></div>`).join('')}</div></div><div class="card"><div class="card-head"><h2>Elections</h2></div><div class="card-body">${s.archive.map(x=>`<div class="list-row"><span>${esc(x.result)}</span><strong>${fmt(x.date)}</strong></div>`).join('')||'<p class="subtle">No completed elections yet.</p>'}</div></div></div>`}
function sharePremiership(){const text=`MANDATE Career — ${s.playerName}\nRole: ${s.opposition?'Leader of the Opposition':s.role}\nParty: ${s.playerParty}\nWeek: ${s.week}\nApproval: ${s.approval}%\nElections fought: ${s.archive.length}`;modal('Premiership Sharing',`<div class="field"><textarea readonly>${esc(text)}</textarea></div><p class="tiny">Copy this summary to share your career.</p>`,`<button class="btn" data-close>Close</button>`)}
function updatesView(){return`<div class="hero"><div><span class="eyebrow">UPDATE 5.0</span><h1>Career Update</h1><p>New career modes, compulsory weekly diaries, opposition continuation, leadership elections, modern map modes, Parliament roster sync and historical-era feedback.</p></div></div><div class="grid grid-3" style="margin-top:12px">${['PM Career Mode','MP Career Mode','Chancellor Career Mode','Electioneer Mode','Voter Career','News Reporter Career','Weekly Diary','Opposition Continuation','Leadership Elections','Premiership Sharing','Historical PM Scenarios','Pre-social-media feedback','Monarch audiences','4-week PM campaigns','25-week Electioneer campaigns','Current Commons roster sync','Interactive UK map','Election Night','Light / Dark theme'].map(x=>`<div class="kpi"><strong style="font-size:17px">${esc(x)}</strong><span>Released</span></div>`).join('')}</div>`}
function settingsView(){return`<div class="grid grid-2"><div class="card"><div class="card-head"><h2>Appearance</h2></div><div class="card-body"><button class="btn" data-action="theme">${s.dark?'Use light theme':'Use dark theme'}</button></div></div><div class="card"><div class="card-head"><h2>Game</h2></div><div class="card-body"><div class="toolbar"><button class="btn" data-action="export">Export save</button><button class="btn danger" data-action="restart">Restart / New Game</button></div></div></div></div>`}
function voterAction(){s.partySupport=pick(PARTIES.slice(0,5));s.voterMood=clamp(s.voterMood+rnd(-5,5),0,100);addNews('Voter preference changes',`Your voter career now leans towards ${s.partySupport}.`,'Voter');save();render()}
function pmqs(){let d=rnd(-3,3);s.approval=clamp(s.approval+d,5,90);addNews(d>=0?'PMQs boosts leadership':'Opposition lands blows at PMQs',d>=0?'The leadership leaves the chamber strengthened.':'A difficult exchange leads the evening bulletins.','Parliament');save();render()}
function rebellion(){s.unity=clamp(s.unity-rnd(2,6),0,100);addNews('Backbench rebellion threatens key vote','Whips begin an urgent operation to limit the rebellion.','Parliament');save();render()}
function lords(){addNews('House of Lords proposes amendments','Peers return legislation to the Commons with changes.','Parliament');save();render()}
function committee(){addNews('Select committee opens hearing','Senior officials and ministers are called to give evidence.','Parliament');save();render()}
function renderControl(){let unlocked=sessionStorage.getItem('mandate-control')==='1';if(!unlocked)return`<div class="setup"><div class="setup-panel"><section class="setup-brand"><div><img src="mandate-logo.svg"><h1>MANDATE CONTROL</h1><p>Separate owner console. Browser-only protection is suitable for game controls, not sensitive information.</p></div></section><section class="setup-form"><form id="controlLogin"><div class="field"><label>Control code</label><input id="controlCode" type="password"></div><button class="btn primary full">Unlock</button></form></section></div></div>`;return`<div class="control-shell"><div class="control-head"><div><span class="eyebrow">OWNER CONSOLE</span><h1>MANDATE CONTROL</h1></div><a class="btn" href="index.html">Return to game</a></div><div class="control-main"><div class="grid grid-3">${kpi('Phase',s.phase,'Current simulation')}${kpi('Role',s.role||'None','Player role')}${kpi('Approval',s.approval+'%','Live save')}</div><div class="grid grid-2" style="margin-top:12px"><div class="card"><div class="card-head"><h2>Live Controls</h2></div><div class="card-body"><div class="toolbar"><button class="btn" data-action="randomEvent">Trigger random event</button><button class="btn" data-action="controlWeek">Advance week</button><button class="btn" data-action="callElection">Call election</button><button class="btn danger" data-action="restart">Reset save</button></div></div></div><div class="card"><div class="card-head"><h2>Metrics</h2></div><div class="card-body"><form id="controlMetrics"><div class="grid grid-2"><div class="field"><label>Approval</label><input id="cApproval" type="number" value="${s.approval}"></div><div class="field"><label>Stability</label><input id="cStability" type="number" value="${s.stability}"></div><div class="field"><label>Unity</label><input id="cUnity" type="number" value="${s.unity}"></div><div class="field"><label>Capital</label><input id="cCapital" type="number" value="${s.capital}"></div></div><button class="btn primary">Apply</button></form></div></div></div></div></div>`}
function render(){document.body.classList.toggle('dark',s.dark);if(location.pathname.endsWith('control.html'))$('#app').innerHTML=renderControl();else if(s.phase==='setup')$('#app').innerHTML=renderSetup();else if(s.phase==='campaign')$('#app').innerHTML=campaignView();else if(s.phase==='election')$('#app').innerHTML=electionView();else $('#app').innerHTML=shell();wire()}
function wire(){$$('[data-career]').forEach(b=>b.onclick=()=>{$$('.career').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#careerType').value=b.dataset.career;$('#scenarioField').style.display=b.dataset.career==='pm'?'grid':'none'});const cf=$('#careerForm');if(cf)cf.onsubmit=e=>{e.preventDefault();startCareer($('#careerType').value,$('#playerName').value,$('#party').value,$('#scenario')?.value)};$$('[data-view]').forEach(b=>b.onclick=()=>{s.view=b.dataset.view;save();render()});$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset));$$('[data-map]').forEach(b=>b.onclick=()=>{s.mapMode=b.dataset.map;save();render()});$$('[data-seat]').forEach(b=>b.onclick=()=>{s.selectedSeat=+b.dataset.seat;save();render()});const cl=$('#controlLogin');if(cl)cl.onsubmit=async e=>{e.preventDefault();if(await sha256($('#controlCode').value)===OWNER_HASH){sessionStorage.setItem('mandate-control','1');render()}else toast('Incorrect control code')};const cm=$('#controlMetrics');if(cm)cm.onsubmit=e=>{e.preventDefault();s.approval=clamp(+$('#cApproval').value,0,100);s.stability=clamp(+$('#cStability').value,0,100);s.unity=clamp(+$('#cUnity').value,0,100);s.capital=clamp(+$('#cCapital').value,0,100);save();toast('Metrics updated');render()}}
function action(a,d){const map={task:()=>completeTask(d.id),endWeek,reshuffle,resignLeadership,confidence,callElection,pmqs,rebellion,lords,committee,syncMPs,newBill,progressBills,budget,mediaEvent,reportStory,worldEvent,sharePremiership,theme:()=>{s.dark=!s.dark;save();render()},export:exportSave,restart,randomEvent:()=>{randomPoliticalEvent();save();render()},controlWeek:endWeek,campaignAction:()=>campaignAction(d),campaignWeek,declare:()=>declare(d),finishElection,voterAction};if(map[a])map[a]()}
function exportSave(){const b=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='mandate-5-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function restart(){if(confirm('Start a completely new political career?')){localStorage.removeItem(SAVE);s=defaultState();render()}}
loadCfg().finally(render);
})();
